float xor(float a, float b) // https://www.shadertoy.com/view/ssG3WK XOR SDF (jt)
{
    // NOTE: XOR can be implemented via sign but sign is buggy on some platforms as spalmer found out.
    return max(min(a, b), -max(a, b));
    // Variants are possible by what iq calls “min-max substitution”,
    // an application of https://en.wikipedia.org/wiki/De_Morgan%27s_laws
    // In context of fuzzy logic (in the case of one-dimensional distance functions):
    // https://en.wikipedia.org/wiki/T-norm might be interesting.
}

float sdBox( vec3 p, vec3 b ) {
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

vec3 erot(vec3 p, vec3 ax, float ro) {
    return mix(dot(p,ax)*ax,p,cos(ro))+sin(ro)*cross(ax,p);
}

#define FK(k) floatBitsToInt(cos(k))^floatBitsToInt(k)
float hash(float a, float b) {
    int x = FK(a), y = FK(b);
    return float((x*x+y)*(y*y-x)-x)/2.14e9;
}

// https://www.shadertoy.com/view/MtsGWH
vec4 boxmap( in sampler2D s, in vec3 p, in vec3 n, in float k )
{
    // project+fetch
	vec4 x = texture( s, p.yz );
	vec4 y = texture( s, p.zx );
	vec4 z = texture( s, p.xy );

    // and blend
    vec3 m = pow( abs(n), vec3(k) );
	return (x*m.x + y*m.y + z*m.z) / (m.x + m.y + m.z);
}


float scene(vec3 p) {
    float cell_z = floor(p.z) + 0.5;
    float neighbor_z = cell_z + ((p.z < cell_z) ? -1.55 : 1.55);

    float hs = round(hash(floor(p.z), 0.) * 4.) / 4.;

    float d = sdBox(p - vec3(hs*0.5,hs*0.5, cell_z), vec3(1., 1., 0.99)) - 0.03;
    float next = sdBox(p - vec3(0., 0., neighbor_z), vec3(1.5, 1.5, 0.99)) - 0.03;

    float s = 1.0;

    for( int m=0; m<2; m++ )
    {  
        p.xy += hs;
        vec3 a = mod( p*s + vec3(0.,0.,sin(iTime) * 0.05), 2.0 )-1.0;
        a.z *= 1.5;
        s *= 3.;
        vec3 r = abs(1.0 - 3.0*abs(a));
        float da = max(r.x,r.y) - 0.03;
        float db = max(r.y,r.z) - 0.03;
        float dc = max(r.z,r.x) - 0.03;
        float c = (xor(da,xor(db,dc))-1.0)/s;

        if( c>d )
        {
          d = c;
        }
    }
    return xor(d, next);
}

vec3 calcNormal( in vec3 pos, in float eps )
{
    vec2 e = vec2(1.0,-1.0)*0.5773*eps;
    return normalize( e.xyy*scene( pos + e.xyy ) + 
					  e.yyx*scene( pos + e.yyx ) + 
					  e.yxy*scene( pos + e.yxy ) + 
					  e.xxx*scene( pos + e.xxx ) );
}

#define RAY_AMT 200

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec2 mouse = (iMouse.xy-0.5*iResolution.xy)/iResolution.y;
    vec3 cam = normalize(vec3(1.5,uv));
    vec3 init = vec3(-6,0,0);

    float yrot = -.3;
    float zrot = 4.1;

    if (iMouse.z > 0.) {
        yrot = clamp(1.-4.*mouse.y,-0.,3.14/2.);
        zrot = 4.*mouse.x;
    }

    cam = erot(cam,vec3(0,1,0),yrot);
    init = erot(init,vec3(0,1,0),yrot);
    cam = erot(cam,vec3(0,0,1),zrot);
    init = erot(init,vec3(0,0,1),zrot);
    init.z = 0.1 * iTime;

    vec3 p = init;
    bool hit = false;
    float rayDist = 0.;
    float f = 0.;
    for (int i = 0; i < RAY_AMT && !hit; i++) {
        float dist = scene(p);
        hit = dist*dist < 1e-6;
        p += dist*cam;
        rayDist = float(RAY_AMT - i)/float(RAY_AMT);
        dist = distance(p,init);
        if(dist>50.)break;
        f += dist;
    }

    vec3 n = calcNormal(p, 0.01);
    vec3 r = reflect(cam, n);
    float colVal = length(sin(r*2.)*.5+.5)/sqrt(3.);
    colVal = colVal*.25 + pow(colVal, 6.);

    vec4 col = vec4(colVal);
    col = mix(col, boxmap( iChannel0, 0.5*p, n, 8.0 ), colVal);
    float occ = clamp(0.4 + 0.6*n.y, 0.0, 1.0);
    col *= occ;

    vec3 rep = vec3(0.1, 0.1, 0.25);

    fragColor = hit ? col : vec4(0.04);

    fragColor = max(fragColor, vec4(1. - rayDist) * 0.8);
    fragColor = sqrt(fragColor);

    fragColor.xyz *= vec3(0.8, 0.8, 1.);
}
